command:
// Outrider's Stellar Attunement. Uses the controlled token, or your assigned character.
const api = game.modules.get("outrider-stellar-attunement")?.api;
if (!api) return ui.notifications.warn("Outrider's Stellar Attunement is not active.");
// Unattuned → Graviton; attuned → swap to the other; second click → Unattuned.
await api.cycle();
